from __future__ import annotations

from pathlib import Path
from typing import Annotated, Literal

from pydantic import Field, model_validator

from kairos_defense.config._types import StrictModel


class PathsConfig(StrictModel):
    duckdb: Path
    truth: Path
    memory: Path
    lancedb: Path
    models: Path
    reports: Path
    exports: Path
    cache: Path  # downloaded models, e.g. FastEmbed (D-084)

    @model_validator(mode="after")
    def _distinct_dbs(self) -> PathsConfig:
        if len({self.duckdb, self.truth, self.memory}) != 3:
            raise ValueError("duckdb, truth and memory must be three different files")
        return self


class EmbeddingsConfig(StrictModel):
    provider: Literal["hashing", "fastembed"]
    dim: Annotated[int, Field(gt=0)]
    fastembed_model: str


class LlmConfig(StrictModel):
    provider: Literal["none", "anthropic", "openai", "ollama"]
    model: str
    base_url: str


class SigningConfig(StrictModel):
    enabled: bool
    key_path: Path


class ReplayConfig(StrictModel):
    default_speed: Literal[1.0, 2.0, 5.0]


class AppConfig(StrictModel):
    paths: PathsConfig
    embeddings: EmbeddingsConfig
    reports_llm_paraphrase: bool
    llm: LlmConfig
    signing: SigningConfig
    replay: ReplayConfig
paths:
  duckdb: data/kairos_defense.duckdb
  truth: data/truth.duckdb          # eval only (CLAUDE.md rule 2)
  memory: data/memory.duckdb
  lancedb: data/lancedb
  models: models
  reports: reports
  exports: exports
  cache: data/cache                 # downloaded embedding models (fetch-models), D-084
embeddings:
  provider: hashing                 # hashing | fastembed
  dim: 384
  fastembed_model: BAAI/bge-small-en-v1.5
reports_llm_paraphrase: false       # if true, cache outputs under data/cache/llm/
llm:
  provider: none                    # none | anthropic | openai | ollama
  model: ""
  base_url: ""                      # for ollama or other OpenAI-compatible servers
signing:
  enabled: true
  key_path: data/keys/ed25519.pem   # generated on first use
replay:
  default_speed: 1.0                # 1.0, 2.0 or 5.0

