    except ValueError:
        return [Check("manifest", "FAIL", f"{MANIFEST} is not JSON")]
    checks = [_files_check(d, manifest), _signature_check(d, mbytes, pubkey_pem)]
    try:
        doc = json.loads((d / "case.json").read_bytes())
    except (OSError, ValueError):
